const isTerminal = (status) => status === 'passed' || status === 'failed';

/**
 * Aggregate a deterministic trial fixture. Incomplete cases are deliberately
 * retained in the result, but are not part of the pass^ denominators.
 * @param {{k?: number, minCases?: number, flakeThreshold?: number, cases?: Array<any>}} fixture
 */
export function aggregateReliability(fixture) {
  const k = Number(fixture?.k ?? 3);
  const minCases = Number(fixture?.minCases ?? 20);
  const flakeThreshold = Number(fixture?.flakeThreshold ?? 0);
  const cases = Array.isArray(fixture?.cases) ? fixture.cases : [];
  const normalized = [];
  let completeCases = 0;
  let passAll = 0;
  let passAny = 0;
  let flakeCases = 0;
  let missing = 0;
  let timeout = 0;
  let crashed = 0;
  let skipped = 0;
  let incompleteCases = 0;
  let anchorViolations = 0;

  for (const input of cases) {
    const trials = Array.isArray(input?.trials) ? input.trials : [];
    const statuses = trials.map((trial) => String(trial?.status ?? 'missing'));
    const complete = statuses.length === k && statuses.every(isTerminal);
    const passed = statuses.filter((status) => status === 'passed').length;
    const firstFailed = statuses[0] === 'failed';
    const laterAllPassed = statuses.length > 1 && statuses.slice(1).every((status) => status === 'passed');
    const flake = complete && firstFailed && laterAllPassed;
    const counts = { missing: 0, timeout: 0, crashed: 0, skipped: 0 };
    for (const status of statuses) {
      if (status in counts) counts[status] += 1;
    }
    missing += counts.missing;\ timeout += counts.timeout; crashed += counts.crashed; skipped += counts.skipped;
    if (!complete) incompleteCases += 1;
    else {
      completeCases += 1;
      if (passed === k) passAll += 1;
      if (passed > 0) passAny += 1;
      if (flake) flakeCases += 1;
    }
    const expected = input?.anchor;
    const anchorOk = expected === 'positive'
      ? complete && passed === k
      : expected === 'negative'
        ? complete && passed === 0
        : true;
    if (!anchorOk) anchorViolations += 1;
    normalized.push({
      id: String(input?.id ?? `case-${normalized.length + 1}`),
      anchor: expected ?? null,
      trials: trials.map((trial, index) => ({ trial: index + 1, status: statuses[index] })),
      complete,
      passed,
      passAtK: complete && passed === k,
      passAtAnyK: complete && passed > 0,
      flake,
      anchorOk,
      incompleteStatuses: counts,
    });
  }
  const rawCaseCount = cases.length;
  const denominator = completeCases;
  const passAtK = denominator ? passAll / denominator : 0;
  const passAtKAny = denominator ? passAny / denominator : 0;
  const flake = denominator ? flakeCases / denominator : 0;
  const safetySkip = normalized.filter((item) => item.anchor === 'safety' && item.incompleteStatuses.skipped > 0).length;
  const safetyFlake = normalized.filter((item) => item.anchor === 'safety' && item.flake).length;
  const reasons = [];
  if (rawCaseCount < minCases || completeCases < minCases) reasons.push('insufficient-sample');
  if (anchorViolations) reasons.push('anchor-violation');
  if (flake > flakeThreshold) reasons.push('flake-threshold-exceeded');
  if (safetySkip || safetyFlake) reasons.push('safety-required-item');
