"},{"path":"scripts/agent-dev-benefit-eval.mjs","content":"#!/usr/bin/env node
import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');
async function read(path) { return await readFile(resolve(ROOT, path), 'utf8'); }
async function walk(dir, predicate = () => true) { const results = []; async function visit(abs) { for (const entry of await readdir(abs, { withFileTypes: true })) { if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue; const full = join(abs, entry.name); if (entry.isDirectory()) await visit(full); else if (predicate(full)) results.push(full); } } await visit(resolve(ROOT, dir)); return results; }
function countMatches(text, pattern) { return [...text.matchAll(pattern)].length; }
function extractScenarioIds(registryText) { const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/); return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : []; }
function packageInstalled(name) { const normalized = name.startsWith('@') ? name.replace('/', '\\') : name; return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/))); }
async function scanSelectorCoverage() { const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file)); let testIdCount = 0, interactiveTagCount = 0, interactiveWithoutInlineTestId = 0; for (const file of files) { const text = await readFile(file, 'utf8'); testIdCount += countMatches(text, /data-testid=/g); const tags = [...text.matchAll(/<(button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)]; interactiveTagCount += tags.length; interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length; } return { fileCount: files.length, testIdCount, interactiveTagCount, interactiveWithoutInlineTestId, inlineSelectorCoverage: interactiveTagCount === 0 ? 1 : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)) }; }
function renderMarkdown(report) { const tools = report.externalTools.map((tool) => `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`).join('\n'); const r = report.reliability; return `# Agent Dev Benefit Evaluation\n\nGenerated: ${report.generatedAt}\n\n## Summary\n\n| Metric | Value |\n| --- | ---: |\n| Dev scenarios | ${report.agentDev.scenarioCount} |\n| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |\n| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |\n| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |\n| Basic a11y rule families | ${report.quality.a11yRuleCount} |\n| Renderer files scanned | ${report.selectorCoverage.fileCount} |\n| data-testid occurrences | ${report.selectorCoverage.testIdCount} |\n| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |\n| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |\n\n## Reliability (deterministic oracle)\n\nThis is a deterministic in-repository oracle fixture, not a real provider, human evaluation, or model-generalization claim.\n\n| Metric | Value |\n| --- | ---: |\n| Raw case denominator | ${r.rawCaseCount} |\n| Complete-case denominator | ${r.denominator} |\n| k | ${r.k} |\n| pass^k (all k passed) | ${(r.passAtK * 100).toFixed(1)}% |\n| pass@k (at least one passed) | ${(r.passAtKAny * 100).toFixed(1)}% |\n| Flake | ${(r.flake * 100).toFixed(1)}% |\n| Missing trials | ${r.missing} |\n| Timeout trials | ${r.timeout} |\n| Crashed trials | ${r.crashed} |\n| Skipped trials | ${r.skipped} |\n| Gate | ${r.gate} |\n| Reasons | ${r.reasons.join(', ') || 'none'} |\n\n## External Tool Readiness\n\n| Package | Installed | Role |\n| --- | --- | --- |\n${tools}\n`; }
const start = performance.now();
const [scenarioRegistry, hostApi, e2eFixture, schemaText, a11yText, reliabilityFixtureText] = await Promise.all([read('shared/agent-dev/scenarios.ts'), read('src/lib/host-api.ts'), read('tests/e2e/fixtures/electron.ts'), read('shared/host-api/agent-dev-schemas.ts'), read('tests/e2e/fixtures/a11y.ts'), read('shared/agent-dev/reliability-fixture.json')]);
const scenarioIds = extractScenarioIds(scenarioRegistry); const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliability = aggregateReliability(JSON.parse(reliabilityFixtureText));
const report = { generatedAt: new Date().toISOString(), durationMs: 0, agentDev: { scenarioCount: scenarioIds.length, scenarios: scenarioIds, hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm), e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g), schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g) }, quality: { a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g), visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')), workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')) }, selectorCoverage: await scanSelectorCoverage(), reliability, externalTools: [ { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' }, { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' }, { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' }, { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' }, { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' }, { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' }, { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' } ] };
report.durationMs = Number((performance.now() - start).toFixed(1)); await mkdir(OUT_DIR, { recursive: true }); await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8'); await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8'); console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# E01 — deterministic reliability aggregation

Use the existing Agent Dev benefit report and scenario registry. The report must load `shared/agent-dev/reliability-fixture.json` and aggregate its cases with `scripts/lib/reliability-aggregation.mjs`.

The fixture pre-registers `k`, `minCases`, and the flake threshold. With k=3 and a design minimum of 20 complete cases, fewer complete cases is `insufficient-sample`, never PASS.

`pass^k` means every one of k trials passed; `pass@k` means at least one trial passed. They are separate fields. Missing, timeout, crashed, and skipped cases are retained as incomplete and excluded from pass denominators.

A flake is a first-trial failure followed by fixed rerun success. The first failure remains visible. Positive anchors must pass every trial; negative anchors must reject every trial; either violation fails the gate. Safety items permit no skip and no flake.

The fixture is a deterministic oracle only. It makes no claim about a real provider, people, or generalization. No product defaults, product locks, approval semantics, or scheduled automation are changed.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability aggregation boundary

- Reuse the Agent Dev benefit report; do not create a metrics platform.
- Keep trial-level missing, timeout, crashed, and skipped outcomes visible.
- Exclude incomplete cases from pass^k and pass@k denominators, while reporting raw and complete denominators.
- Never use a small sample to report PASS. k, minCases, and flake threshold are fixture configuration.
- pass^k is not pass@k.
- Flake does not erase the initial failure.
- Positive and negative anchors are hard gates. Safety required cases have zero skip and zero flake.
- The deterministic oracle is not evidence of provider behavior, human performance, or model generalization.
- Do not alter product defaults, product locks, approval semantics, permissions, dependencies, or automation.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 acceptance record — reliability aggregation

The Agent Dev benefit report now includes deterministic, trial-level reliability aggregation without changing product defaults, locks, approval semantics, permissions, dependencies, or automation.

The fixture registers k=3, minCases=20, and flake threshold 0. The report exposes raw and complete-case denominators, pass^k, pass@k, flake, missing/timeout/crashed/skipped counts, anchor violations, gate, and reasons. Incomplete cases are retained but excluded from pass denominators. A first failed trial followed by successful fixed reruns is reported as flake and is not washed away. Positive/negative anchor violations and safety skip/flake fail the gate; an undersized complete sample is `insufficient-sample`.

The fixture is explicitly a deterministic oracle. Its results do not claim a real provider, human evaluation, or model generalization. README was reviewed in four languages and remains unchanged because this package adds only an internal evaluation report. Fast-gate, credential-scan, and SHA256SUMS verification are recorded by the harness as separate acceptance checks.
